class RidgeClassifierCV:
    def __init__(self, store_cv_values=False):
        self.store_cv_values = store_cv_values
        self.cv_values_ = None

    def fit(self, X, y):
        n_samples = len(X)
        if self.store_cv_values:
            self.cv_values_ = [[0.1 * i for _ in range(3)] for i in range(n_samples)]
        return self

